function toast(m){const e=document.createElement('div');e.className='toast';e.textContent=m;document.body.append(e);setTimeout(()=>e.remove(),2400)}
function streak(){let c=0;const d=new Date();if(!S.days.includes(D()))d.setDate(d.getDate()-1);const f=x=>x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');while(S.days.includes(f(d))){c++;d.setDate(d.getDate()-1)}return c}
var XCAP=250;
function xpToday(){return(S.xl||[]).filter(e=>e.d===D()).reduce((a,e)=>a+e.n,0)}
function addXp(n,p){const o=lvl(),n0=n,room=Math.max(0,XCAP-xpToday());n=Math.min(n0,room);const pp=n0?Math.round((p??Math.ceil(n0/2))*n/n0):0;if(n>0){S.xp+=n;(S.xl=S.xl||[]).push({d:D(),n});if(S.xl.length>400)S.xl.shift();S.pxp+=pp;const pt=growPet(),sg=pt?stg(pt):0;if(pt){pt.x+=pp;if(stg(pt)>sg)pgUp(pt)}}if(!S.days.includes(D()))S.days.push(D());save();chk();if(n<=0){toast(t('xcl'));return 0}if(lvl()>o){toast(t('up')+' '+LN[lvl()-1]+(nt(lvl())?' • +'+nt(lvl())+' '+t('themes'):''));vib([100,60,100,60,300])}else toast('+'+n+' XP');return n}
function chk(){const c=[S.tasks.filter(x=>x.paid).length>=1,S.tasks.filter(x=>x.paid).length>=5,S.sess.length>=1,S.gc>=3,streak()>=3,S.badges.includes('b5')];['b0','b1','b2','b3','b4'].forEach((b,i)=>{if(c[i]&&!S.badges.includes(b)){S.badges.push(b);toast(t('bdg')[i]);save()}})}
const gk=g=>g.p==='d'?D():'w'+wk();
function prog(){const T=D(),g=S.goals.filter(x=>x.p==='d'),gd=g.filter(x=>x.done===T).length,tk=S.tasks.filter(x=>x.at===T||(!x.done&&x.date===T)),td=tk.filter(x=>x.done).length,n=g.length+tk.length;return n?Math.round((gd+td)/n*100):0}
const dl=d=>{const n=Math.round((new Date(d+'T00:00')-new Date(D()+'T00:00'))/864e5);return n<0?t('past'):n===0?t('tod'):n+' '+t('left')};
function form(title,fs,v,cb,ok='save'){const d=document.createElement('dialog');d.innerHTML=`<form><h3>${esc(title)}</h3>${fs.map(f=>`<label>${t(f.l)}${f.t==='area'?`<textarea name=${f.k} rows=5></textarea>`:f.t==='sel'?`<select name=${f.k}>${f.o.map(o=>`<option value="${o[0]}">${f.raw?esc(o[1]):t(o[1])}</option>`).join('')}</select>`:`<input name=${f.k} type=${f.t}${f.r?' required':''}>`}</label>`).join('')}<div class=row><button class=btn>${t(ok)}</button><button type=button class="btn g" data-x>${t('cancel')}</button></div></form>`;document.body.append(d);const fm=d.querySelector('form');fs.forEach(f=>fm.elements[f.k].value=v[f.k]??f.d??'');d.querySelector('[data-x]').onclick=()=>d.close();d.onclose=()=>d.remove();fm.onsubmit=e=>{e.preventDefault();const o={};fs.forEach(f=>o[f.k]=fm.elements[f.k].value.trim());d.close();cb(o)};d.showModal()}
