const LF=[['cards','🗂️','cards'],['gpa','🧮','gpa'],['tt','🗓️','tt'],['focus','🔒','focus'],['wish','⭐','wish'],['album','📷','album'],['chal','🏁','chal'],['plist','🎵','plist'],['subs','🏷️','subjects']];
const fld=(k,l,ty='text',r=1)=>({k,t:ty,l,r}),dn7=i=>new Date(2024,0,7+i).toLocaleDateString(LC[S.lang],{weekday:'long'});
function stk(a){let c=0;const d=new Date();if(!a.includes(DS(d)))d.setDate(d.getDate()-1);while(a.includes(DS(d))){c++;d.setDate(d.getDate()-1)}return c}
function DS(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
