V.cards=()=>{FQ=FQ||S.fc.filter(c=>(c.due||0)<=dayNo()&&inF(c)).map(c=>c.id);const c=S.fc.find(x=>x.id===FQ[0]);
return hd(t('cards'),1)+sbChips()+(c?`<button class="card ctr fc" data-a=fflip><p class=mu>${sbDot(c.sb)}${esc(c.s)} — ${FQ.length}</p><h3>${esc(c.q)}</h3>${FF?`<p class=q>${esc(c.a)}</p>`:`<p class=mu>${t('flip')}</p>`}</button>${FF?`<div class=row><button class="btn g grow" data-a=fag>${t('ag')}</button><button class="btn grow" data-a=fkn>${t('kn')}</button></div>`:''}`:`<div class="card empty">${t('fdone')}</div>`)+`<button class=btn data-a=fadd>+ ${t('add')}</button>`+S.fc.filter(inF).map(x=>`<div class="card item"><div class=grow><b>${esc(x.q)}</b><p class=mu>${sbDot(x.sb)}${esc(x.s)}</p></div><button class="btn g s" data-a=fdel data-i=${x.id} aria-label="${t('del')}">✕</button></div>`).join('')};
V.gpa=()=>{const sc=S.gsc,cr=S.gp.reduce((a,x)=>a+x.c,0),sm=S.gp.reduce((a,x)=>a+x.c*x.m,0);return hd(t('gpa'),1)+`<div class="card ctr"><p class=mu>${t('avg')} / ${sc}</p><h1 class=big>${cr?(sm/cr).toFixed(2):'—'}</h1><p class=mu>${cr} ${t('cr')}</p></div><div class=row><button class=btn data-a=gpadd>+ ${t('add')}</button><button class="btn g" data-a=gpneed>${t('need')}</button><button class="btn g" data-a=gpsc>${t('scale')}</button></div>`+(S.gp.length?S.gp.map(x=>`<div class="card item"><div class=grow><b>${esc(x.n)}</b><p class=mu>${x.m}/${sc} — ${x.c} ${t('cr')}</p></div><button class="btn g s" data-a=gpdel data-i=${x.id} aria-label="${t('del')}">✕</button></div>`).join(''):empty())};
V.tt=()=>{const n=new Date(),hm=String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0'),srt=a=>a.sort((x,y)=>x.st<y.st?-1:1);let nx=null;for(let o=0;o<7&&!nx;o++){const d=(n.getDay()+o)%7;nx=srt(S.tt.filter(x=>+x.day===d&&(o>0||x.st>hm)))[0];if(nx)nx={...nx,o,d}}
return hd(t('tt'),1)+`<button class=btn data-a=ttadd>+ ${t('add')}</button>`+(nx?`<div class=card><p class=mu>${t('nxl')}</p><h3>${esc(nx.n)}</h3><p>${nx.o?dn7(nx.d):t('tod')} — ${nx.st}–${nx.et} ${nx.r?'— '+esc(nx.r):''}</p></div>`:`<div class="card empty">${t('nol')}</div>`)+[0,1,2,3,4,5,6].map(d=>{const l=srt(S.tt.filter(x=>+x.day===d));return l.length?`<h3 class=sec>${dn7(d)}${n.getDay()===d?' •':''}</h3>`+l.map(x=>`<div class="card item"><div class=grow><b>${esc(x.n)}</b><p class=mu>${x.st}–${x.et} ${esc(x.r)}</p></div><button class="btn g s" data-a=ttdel data-i=${x.id} aria-label="${t('del')}">✕</button></div>`).join(''):''}).join('')};
V.focus=()=>FM.on?`<div class="card ctr fmc"><p class=mu>${t('fhint')}</p><div class="ring big" id=fr style="--p:${Math.round((1-fleft()/(FM.mins*60))*100)}"><b id=ft>${fm(fleft())}</b></div><button class="btn g" data-a=fgive>${t('fgive')}</button></div>`:hd(t('focus'),1)+`<div class="card ctr"><p class=mu>${t('fmin')}</p><div class=tabs>${[15,25,45,60].map(n=>`<button class="${FM.mins===n?'on':''}" data-a=fmin data-i=${n}>${n}</button>`).join('')}</div><button class=btn data-a=fgo>${t('fgo')}</button></div>`;
setInterval(()=>{if(!FM.on)return;const l=fleft(),e=$('#ft');if(e){e.textContent=fm(l);$('#fr').style.setProperty('--p',Math.round((1-l/(FM.mins*60))*100))}if(!l){FM.on=false;document.body.classList.remove('focus');S.sess.push({d:D(),m:FM.mins});beep();{const x=Math.min(50,Math.max(1,Math.round(FM.mins)));addXp(x,Math.round(x*.8))}toast(t('fgood'));notify(t('fgood'));vib([200,100,200,100,400]);render()}},500);
V.wish=()=>hd(t('wish'),1)+`<button class=btn data-a=wsadd>+ ${t('add')}</button>`+(S.wl.length?[...S.wl].sort((a,b)=>(a.on?1:0)-(b.on?1:0)||PO[a.p]-PO[b.p]).map(x=>`<div class="card item ${x.on?'dn':''}"><button class="ck ${x.on?'on':''}" data-a=wsck data-i=${x.id} aria-label="${t('got')}"></button><div class=grow><b>${esc(x.t)}</b><p class=mu><span class="pr ${x.p}">${t(PRL[x.p])}</span> ${t('wc'+x.c)}</p></div><button class="btn g s" data-a=wsdel data-i=${x.id} aria-label="${t('del')}">✕</button></div>`).join(''):empty());
V.album=()=>hd(t('album'),1)+`<div class=row><button class=btn data-a=aph>${t('aph')}</button><button class="btn g" data-a=ano>${t('anote')}</button></div><input id=af type=file accept="image/*" hidden data-c=af>`+(S.al.length?[...S.al].sort((a,b)=>a.d<b.d?1:-1).map(x=>`<div class=card>${x.i?`<img class=ph src="${x.i}" alt="">`:''}<p style="white-space:pre-wrap">${esc(x.x)}</p><div class=row><span class="mu grow">${x.d}</span><button class="btn g s" data-a=adel data-i=${x.id} aria-label="${t('del')}">✕</button></div></div>`).join(''):empty());
V.chal=()=>{const ok=S.dc.includes(D());return hd(t('chal'),1)+`<div class="card ctr"><p class=q>${t('chl')[dayNo()%8]}</p><button class="btn ${ok?'g':''}" data-a=cdo>${ok?'✓ ':''}${t('chd')}</button></div><div class="card row"><div class=grow><p class=mu>${t('streak')}</p><h2>${stk(S.dc)}</h2></div><div class=grow><p class=mu>${t('chn')}</p><h2>${S.dc.length}</h2></div></div>`};
V.plist=()=>hd(t('plist'),1)+`<div class=chips style="margin-bottom:.8rem"><button class="chip ${PF<0?'on':''}" data-a=pf data-i=-1>${t('all')}</button>${t('moods').map((m,i)=>`<button class="chip ${PF===i?'on':''}" data-a=pf data-i=${i}>${m}</button>`).join('')}</div><button class=btn data-a=pladd>+ ${t('add')}</button>`+(S.pl.filter(x=>PF<0||x.k===PF).map(x=>`<div class="card item"><div class=grow><a href="${esc(x.u)}" target=_blank rel="noopener noreferrer"><b>${esc(x.t)}</b></a><p class=mu>${t('moods')[x.k]}</p></div><button class="btn g s" data-a=pldel data-i=${x.id} aria-label="${t('del')}">✕</button></div>`).join('')||empty());
function photo(f){const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,640/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*k;c.height=im.height*k;c.getContext('2d').drawImage(im,0,0,c.width,c.height);const u=c.toDataURL('image/jpeg',.65);form(t('album'),[fld('x','cap','text',0),fld('d','date','date')],{d:D()},v=>{S.al.push({id:S.nid++,d:v.d||D(),x:v.x,i:u});save();render()})};im.onerror=()=>toast('Image error');im.src=r.result};r.readAsDataURL(f)}
