gpdel:i=>{S.gp=S.gp.filter(x=>x.id!=i);save();render()},
gpsc:()=>form(t('scale'),[fld('s','scale','number')],{s:S.gsc},v=>{S.gsc=Math.max(1,+v.s||20);save();render()}),
gpneed:()=>form(t('need'),[fld('g','target','number'),fld('c','ncr','number')],{},v=>{const cr=S.gp.reduce((a,x)=>a+x.c,0),sm=S.gp.reduce((a,x)=>a+x.c*x.m,0),c=+v.c;if(!(c>0))return;const n=(+v.g*(cr+c)-sm)/c;toast(t('need')+': '+Math.max(0,n).toFixed(2)+(n>S.gsc?' ⚠ >'+S.gsc:''))}),
