ttdel:i=>{S.tt=S.tt.filter(x=>x.id!=i);save();render()},
fmin:i=>{FM.mins=+i;render()},fgo:()=>{FM.on=true;FM.end=Date.now()+FM.mins*6e4;document.body.classList.add('focus');render()},
