wsck:i=>{const x=S.wl.find(y=>y.id==i);x.on=!x.on;if(x.on&&!x.paid){x.paid=1;addXp(5)}save();render()},wsdel:i=>{S.wl=S.wl.filter(x=>x.id!=i);save();render()},
aph:()=>$('#af').click(),ano:()=>form(t('album'),[fld('x','body','area'),fld('d','date','date')],{d:D()},v=>{S.al.push({id:S.nid++,d:v.d||D(),x:v.x,i:''});save();render()}),adel:i=>{S.al=S.al.filter(x=>x.id!=i);save();render()},
